  // a prompt like "Bump the version marker to ...-2026-07-19 (today's date), commit
  // to GitHub, deploy to Render, verify /health" must route to the developer
  // executor, not return "The answer is 2019." as a math/time query.
  const hasCommitSignal = /\b(commit|push\s+(?:to\s+)?github|github\s+main|pr\s*#\d)\b/.test(normalized);
  const hasDeploySignal = /\b(deploy|render|trigger\s+a\s+deploy|live\s+commit|production\s+commit)\b/.test(normalized);
  const hasVerifySignal = /\b(verify|verified\s+evidence|verify\s+the\s+live|live\s+runtime\s+commit|github\s+head|sha\s+match|\/health)\b/.test(normalized);
  const hasMutationSignal = /\b(bump|update|change|edit|modify|patch|fix|migrate|rollback)\b/.test(normalized)
    && /\b(version|marker|file|endpoint|route|table|policy|config|code|production)\b/.test(normalized);
  const executionSignalCount = [hasCommitSignal, hasDeploySignal, hasVerifySignal, hasMutationSignal].filter(Boolean).length;
  if (executionSignalCount >= 2) {
    return true;
  }

  // App-scaffold / new-app-from-scratch signals — explicit owner commands to
  // CREATE a new app, scaffold a new project, build a new module from scratch,
  // or run a stress/load test. These are real code-production requests the
  // senior developer worker handles (create_file patch operations), NOT
  // planning/narrative prompts. Without this guard, the planner mis-routes
  // them to app_build_planning → gpt_conversation (narrative GPT-4o answer)
  // and the senior developer never runs. Closes the PARTIAL item gap where
  // "create a new app from scratch" returned a narrative plan instead of
  // real scaffolded files.
  const hasAppScaffoldSignal = /\b(?:create|scaffold|build|generate)\s+(?:a\s+)?(?:new\s+)?(?:app|application|module|service)\s+(?:from\s+scratch|project|skeleton|shell|template|called\s+|named\s+)/i.test(normalized)
    || /\bnew\s+app\s+from\s+scratch/i.test(normalized)
    || /\bscaffold\s+(?:a\s+)?(?:new\s+)?(?:app|project|module)/i.test(normalized);
  const hasStressTestSignal = /\bstress\s*test/i.test(normalized)
    || /\bload\s*test/i.test(normalized)
    || /\brun\s+a\s+(?:stress|load)\s+test/i.test(normalized);
  if (hasAppScaffoldSignal || hasStressTestSignal || isServerBugFixRequest(normalized) || asksToCreateAndShowProof(normalized)) {
    return true;
  }

  return false;
}

function asksForLongStructuredResponse(normalized: string): boolean {
  return /\b(full\s+list|complete\s+list|list\s+all|enumerate|from\s+1\s+to\s+\d+|1\s*[-–to]+\s*\d+|one\s+to\s+\d+|\d{2,}\s+(?:items?|points?|things?|steps?|rows?|entries|checks?))\b/.test(normalized)
    // Full / structured audits always need the long-response budget + auto-continuation.
    || /\b(full\s+audit|complete\s+audit|end[-\s]?to[-\s]?end\s+audit|audit\s+(?:everything|all|end\s+to\s+end|one\s+by\s+one)|run\s+(?:a\s+)?full\s+audit|audit\s+\d{1,4}\s*[-–to]+\s*\d{1,4}|audit\s+from\s+1)\b/.test(normalized)
    // Any explicit numeric range whose upper bound is large (e.g. "1-100", "1 to 2000").
    || hasLargeExplicitRange(normalized);
}

export function hasLargeExplicitRange(normalized: string): boolean {
  const match = normalized.match(/\b(?:from\s+)?1\s*(?:[-–]|to)\s*(\d{2,4})\b/);
  if (match) {
    const upper = Number.parseInt(match[1], 10);
    return Number.isFinite(upper) && upper >= 30;
  }
  return false;
}

function asksForMultiStepTask(normalized: string): boolean {
  return /\b(step[-\s]?by[-\s]?step|multi[-\s]?step|decompose|break\s+(?:it|this)?\s*down|task\s+decomposition|execution\s+plan|implementation\s+plan|roadmap|sequence)\b/.test(normalized)
    || /\b(build|fix|audit|implement|ship|repair|improve)\b.{0,80}\b(plan|steps|phases|tasks)\b/.test(normalized);
}

export function asksForDealReview(normalized: string): boolean {
  return /\b(review\s+(?:this\s+)?deal|deal\s+review|underwrite|underwriting|cap\s+rate|noi|cash[-\s]?on[-\s]?cash|real\s+estate\s+deal|investment\s+deal)\b/.test(normalized);
}

export function asksForBugReview(normalized: string): boolean {
  return /\b(what\s+bugs?\s+do\s+you\s+see|find\s+bugs?|bug\s+review|bug\s+list|prioritized\s+bug\s+list|review\s+(?:the\s+)?bugs?|errors?\s+do\s+you\s+see|what\s+is\s+broken)\b/.test(normalized)
    || /\binspect\b.{0,100}\b(?:chat|ai|assistant)\b.{0,100}\bbugs?\b/.test(normalized);
}

/**
 * Detects when the owner wants to SEE real source code from the repository —
 * file paths, functions, endpoints, queries, or a feature's implementation —
 * rather than execute a build/fix task. These requests must be grounded in the
 * live repo (code search) so the answer contains concrete files and source,
 * never a generic LLM guess or a clarification question.
 */
export function asksForCodeRetrieval(normalized: string): boolean {
  const codeNoun = /\b(code|source|source\s+code|snippet|implementation|function|method|class|file|files|file\s+path|endpoint|route|api\s+route|handler|query|queries|sql\s+quer(?:y|ies)|service|module|component|schema\s+definition)\b/;
  const retrievalVerb = /\b(show|give|return|see|read|display|paste|get|list|find|reveal|provide|where\s+is|which\s+file|what\s+file|locate|share)\b/;
  // "show me the analytics code", "return the analytics implementation", "where is the auth endpoint"
  if (retrievalVerb.test(normalized) && codeNoun.test(normalized)) {
    return true;
  }
  // Direct phrasings that always imply real code retrieval.
  return /\b(source\s+code|code\s+for|implementation\s+of|implementation\s+details|actual\s+code|real\s+code|how\s+is\s+\w+\s+implemented|how\s+does\s+\w+\s+work\s+in\s+(?:the\s+)?code|file\s+path|function\s+name|endpoint\s+definition|database\s+quer(?:y|ies)\s+used)\b/.test(normalized);
}

/**
 * Detects open-ended app/product build requests like "build an app like TikTok",
 * "create a clone of Uber", "I want to build a marketplace app". These must NOT
 * fall through to a generic conversational timeline. They trigger a senior product-
 * engineering planning response: architecture proposal, module breakdown, required
 * repo/actions, execution plan, and a permission/capability check — not boilerplate.
 *
 * Deliberately excludes prompts that already point at THIS repo's concrete work
 * ("build the feature", "build this screen"), which belong to self-developer execution.
 */
/**
 * Detects an owner request to GENERATE a 3D model / mesh / render (e.g.
 * "generate a 3d model of a villa", "create a 3D render of our product",
 * "make me a 3d mesh of a chair"). Routes to the owner 3D generation tool
 * (Meshy/Tripo direct, or a deterministic procedural Three.js preview).
 *
 * Deliberately excludes "build an app" / generic build requests by requiring an
 * explicit 3D/mesh/render target word.
 */
export function asksToGenerate3DModel(normalized: string): boolean {
  const genVerb = /\b(generate|create|make|build|render|design|produce|model|sculpt|give\s+me|i\s+want|i\s+need)\b/;
  const threeDTarget = /\b(3d|three[\s-]?d)\b/;
  const meshTarget = /\b(3d\s+model|3d\s+render|3d\s+mesh|3d\s+object|3d\s+asset|mesh|render)\b/;
  if (!genVerb.test(normalized)) {
    return false;
  }
  if (threeDTarget.test(normalized)) {
    return true;
  }
  // "model/mesh/render" without "3d" only counts when paired with a clear object word.
  return meshTarget.test(normalized) && /\b(model|mesh|render|object|asset|figure|statue|product|prototype|scene)\b/.test(normalized);
}

/**
 * Detects a short, imperative server bug/crash/fix request that must execute
 * via the senior-developer runtime rather than fall through to a conversational
 * GPT answer. Catches prompts like "fix server crash", "server is down", "fix
 * the server issue", "resolve the backend crash" — these are concrete in-repo
 * engineering tasks, not general questions. Without this signal the prompt is
 * too short to register as a task block and the reliability gate blocks the
 * GPT answer with a contradictory STATE: BLOCKED message.
 */
export function isServerBugFixRequest(normalized: string): boolean {
  // Imperative "fix server ..." / "fix the server ..." / "fix backend/api ..."
  const fixServer = /\bfix\s+(?:the\s+)?(?:server|backend|api)\b/i.test(normalized);
  // Declarative server/backend/api crash / is down / outage / failure / error
  const serverIncident = /\b(?:server|backend|api)\s+(?:is\s+|are\s+)?(?:crash|crashes|crashed|down|outage|offline|failing|failure|failures|error|errors|bug|bugs|issue|issues)\b/i.test(normalized);
  // Imperative "fix server crash" / "fix backend outage" / "fix api error" (with specific noun)
  const fixServerSpecific = /\bfix\s+(?:the\s+)?(?:server|backend|api)\s+(?:crash|crashes|outage|error|errors|failure|failures|issue|issues|bug|bugs)\b/i.test(normalized);
  return fixServer || serverIncident || fixServerSpecific;
}

/**
 * Detects owner prompts that demand a real creation/build be shown/proven in the chat
 * (e.g. "create and show me a chat module", "build me a feature and prove it",
 * "make the developer text and show me"). These are execution commands, not status
 * questions or tutorial requests. The phrase "I want to see if you are senior developer"
 * was wrongly answered with a static capability description because the router did not
 * recognize the first half of the message as an execution signal. This detector closes
 * that gap: when a create/build verb and a show/proof verb both appear with a code/UI
 * target, the senior-developer runtime executes end-to-end and returns live proof.
 */
export function asksToCreateAndShowProof(normalized: string): boolean {
  // A "how to" / tutorial request is informational, not an execution command.
  if (/\bhow\s+to\b/.test(normalized)) {
    return false;
  }
  const createVerb = /\b(create|make|build|code|develop|implement|add|wire|generate|write|design)\b/;
  const showProof = /\b(show|prove|demonstrate|display|see|deploy|ship|verify|give\s+me)\b/;
  const target = /\b(chat|module|component|screen|feature|fix|app|page|text|developer|backend|api|route|function|file|code|ui|dashboard|engine|pipeline|system|platform|workflow|bug|issue|error|patch|feature|interface)\b/;
  if (!createVerb.test(normalized) || !target.test(normalized)) {
    return false;
  }
  // "create X and show me" / "build X and prove it" / "make X and deploy it"
  const createAndShow = /\b(?:create|make|build|code|develop|implement|add|wire|generate|write|design)\b.{0,80}\b(?:and|then)\s+(?:show|prove|demonstrate|display|deploy|ship|verify)\b/i.test(normalized);
  // "show me the X you create" / "I want to see X created/built" / "give me the X"
  const showThenCreate = showProof.test(normalized) && /\b(?:you|it|this|that|the)\s+(?:create|build|make|code|develop|implement|add|generate|write|design)\b/i.test(normalized);
  // "I want to see if you can create/build X" / "see if you can make X" (screenshot prompt)
  const wantToSeeCreation = /\b(?:i\s+want\s+to\s+see|see\s+if)\s+(?:you\s+)?(?:can\s+)?(?:create|build|make|code|develop|implement|write|design)\b/i.test(normalized)
    || /\b(?:create|build|make|code|develop|implement|write|design)\b.{0,60}\b(?:and\s+show|and\s+prove|and\s+deploy|to\s+show|to\s+prove|to\s+deploy)\b/i.test(normalized);
  return createAndShow || showThenCreate || wantToSeeCreation;
}

export function asksToBuildApp(normalized: string): boolean {
  // "build/create/make/design/develop ... an/a/another ... app/clone/platform/product/mvp/saas/marketplace/..."
  const buildVerb = /\b(build|create|make|design|develop|spin\s+up|launch|clone|ship)\b/;
  const appNoun = /\b(app|application|clone|platform|product|mvp|saas|marketplace|startup|website|web\s+app|mobile\s+app|social\s+(?:app|network|platform)|dating\s+app|delivery\s+app|fintech\s+app)\b/;
  // "like X" / "such as X" / "similar to X" / "version of X" / "clone of X" strongly implies product planning.
  const comparativeApp = /\b(?:app|clone|platform|product|version|something)\b[^.]{0,40}\b(?:like|similar\s+to|such\s+as)\b/;
  const cloneOf = /\b(clone|version|copy)\s+of\s+\w+/;

  // A build command aimed at the owner's OWN IVX system ("build the IVX engine",
  // "create our investment platform", "finish the autonomous engine") is in-repo
  // EXECUTION, not a request to scaffold a brand-new external product. It must never
  // enter narrative "app planning" mode — it routes to the senior-developer runtime.
  if (targetsOwnSystemBuild(normalized)) {
    return false;
  }
  if (cloneOf.test(normalized) || comparativeApp.test(normalized)) {
    return true;
  }
  if (buildVerb.test(normalized) && appNoun.test(normalized)) {
    // Avoid hijacking concrete in-repo execution like "build the screen"/"build this feature".
    const pointsAtThisRepoWork = /\b(this|that|the)\s+(feature|screen|fix|bug|endpoint|route|module|component|migration|page|function|test)\b/.test(normalized);
    return !pointsAtThisRepoWork;
  }
  return false;

}

// --- Self-Developer Execution: real senior developer runtime via the persistent worker queue ---
// CHAT ↔ WORKER SYNC: trigger on EITHER the legacy planner's self_developer
// route OR the unified 5-branch router's developer_executor branch. The
// unified router (routeIVXChatIntent) classifies audit/verify/smoke-test/
// build/fix/deploy/QA/recovery/database/production-verification prompts as
// developer_executor even when the legacy keyword planner does not map them
// to self_developer. Without this OR, those prompts fall through to the
// narrative GPT path — which is exactly the bug this fix closes.
// ── READ-ONLY INSPECTION ROUTE (owner mandate 2026-07-19) ──────────────
// Read-only technical inspection prompts ("inspect the chat ordering issue
// and report the current task status; do not change or deploy anything")
// MUST route through the persistent worker queue as a READ_ONLY job — never
// through the narrative fallback model. This closes the gap where an
// inspection prompt fell through to GPT, which then mentioned files it
// "inspected" and tripped the Fake Execution Gate.
//
// The classifier fires BEFORE the developer_executor branch so a read-only
// signal combined with an inspection signal wins over the generic audit/
// fix matchers in the 10-category execution list. The worker runs the
// read-only runtime (no file edits / commit / deploy / migrations) and
// returns the strict inspection format (TASK ID / STATUS / MODE: READ_ONLY /
// FILES INSPECTED / COMMANDS RUN / FINDINGS / ROOT CAUSE / FILES CHANGED:
// NONE / COMMIT: NOT REQUESTED / DEPLOYMENT: NOT REQUESTED).
const inspectionClassification = classifyExecutionModeIntent(prompt);
const isReadOnlyInspection = inspectionClassification.isExecutionMode
  && inspectionClassification.category === 'developer_inspection';
if (isReadOnlyInspection) {
  const workerOwnerId = ownerContext.userId ?? 'owner';
  const inspectionWorkerInput: IVXWorkerJobInput = {
    goal: prompt,
    ownerApproved: true,
    // Read-only mode: the worker's read-only branch ignores these flags,
    // but we set them false so the audit contract is explicit.
    approvePatch: false,
    approveGitDeploy: false,
    validationMode: 'focused',
    systemMode: false,
    executionMode: 'read_only',
    ownerApprovedAction: {
      proposedPlan: prompt.slice(0, 500),
      filesAffected: [],
      riskLevel: 'low',
      rollbackOption: '',
      rollbackAvailable: false,
      auditLog: [
        `source=ivx_ia_chat`,
        `conversationId=${conversation.id}`,
        `requestId=${requestId}`,
        `ownerId=${workerOwnerId}`,
        `executionMode=read_only`,
        `matchedTrigger=${inspectionClassification.matchedTrigger}`,
      ],
      secretValuesReturned: false as const,
    },
    ownerId: workerOwnerId,
  };

  const { job: enqueuedInspectionJob, attached: inspectionAttached, activeJobId: inspectionActiveJobId } = await enqueueOrAttachSeniorDeveloperJob(inspectionWorkerInput);
  const inspectionTaskId = enqueuedInspectionJob.jobId;
  console.log('[IVXOwnerAIBackend] chat→worker (read-only inspection):', {
    taskId: inspectionTaskId,
    attached: inspectionAttached,
    activeJobId: inspectionActiveJobId,
    ownerId: workerOwnerId,
    conversationId: conversation.id,
    matchedTrigger: inspectionClassification.matchedTrigger,
  });

  // Bounded warmup so the first status payload reflects real inspection
  // progress, not just "queued". Cap at 12s so we stay well under the HTTP
  // 60s budget; the Expo client polls the statusUrl for the rest.
  const INSPECTION_WARMUP_INTERVAL_MS = 750;
  const INSPECTION_WARMUP_TIMEOUT_MS = 12_000;
  const inspectionWarmupDeadline = Date.now() + INSPECTION_WARMUP_TIMEOUT_MS;
  let inspectionJob: IVXWorkerJob = enqueuedInspectionJob;
  const inspectionIsTerminal = (st: IVXWorkerJob['status']): boolean =>
    st === 'completed' || st === 'failed' || st === 'blocked' || st === 'cancelled';
  const inspectionHasAdvanced = (st: IVXWorkerJob['status']): boolean => st !== 'queued';
  while (!inspectionIsTerminal(inspectionJob.status) && !inspectionHasAdvanced(inspectionJob.status) && Date.now() < inspectionWarmupDeadline) {
    await new Promise((resolve) => setTimeout(resolve, INSPECTION_WARMUP_INTERVAL_MS));
    const fresh = await getSeniorDeveloperJob(inspectionTaskId);
    if (fresh) inspectionJob = fresh;
  }
  // If the worker advanced past queued, keep polling briefly so a fast
  // inspection returns its final evidence in the same response.
  if (!inspectionIsTerminal(inspectionJob.status) && inspectionHasAdvanced(inspectionJob.status)) {
    const extraDeadline = Math.min(Date.now() + 8_000, inspectionWarmupDeadline + 8_000);
    while (!inspectionIsTerminal(inspectionJob.status) && Date.now() < extraDeadline) {
      await new Promise((resolve) => setTimeout(resolve, INSPECTION_WARMUP_INTERVAL_MS));
      const fresh = await getSeniorDeveloperJob(inspectionTaskId);
      if (fresh) inspectionJob = fresh;
    }
  }

